"""
Evaluate matrix-valued modular coherence and both one-sided responses.

The transverse MDM localization observable is evaluated separately for each disorder batch. The response extension follows each direction of the supplied density tangent, including zero coherences and tied leading spectral channels.

Returns
-------
return curves
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

def modular_batch_curves(deltas: 'np.ndarray | list | tuple', distances: 'np.ndarray | list | tuple', trim: int, width: int) -> 'np.ndarray':
    """Parameters
    ----------
    deltas : array_like, shape (B,S,2,P,P)
        Finite real or complex addition jets, B,S,P>=1. Axis 2 contains Delta and Delta'.
    distances : array_like
        Nonempty vector of integer separations 0<=d<L-2*trim, preserving order and repetitions.
    trim : int
        Nonnegative number of complete slices removed at each end.
    width : int
        Positive slice width dividing P; L=P/width.
    
    Returns
    -------
    curves : real ndarray, shape (B,3,len(distances))
        Rows of the second axis are the source MDM decay observable gamma and its right directional derivatives gamma'_+, gamma'_-. The source MDM prescription acts on Delta+alpha*Delta'; transverse entry (a,b), 0<=a,b<width, uses sites (width*x+a,width*(x+d)+b), with an equal mean over all samples of the batch and x=trim,...,L-trim-d-1. Base entries with magnitude <=1e-12 are replaced by zero for this local linearization. Gamma'_sigma differentiates the resulting observable in direction sigma*Delta', sigma=+1,-1, at alpha=0 from positive alpha. All eigenvalues within 1e-10*max(gamma,1e-300) of the leading spectral value form the top eigenspace for this derivative. Invalid domains raise ValueError."""
    return None

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np

def _oracle_modular_batch_curves(deltas: 'np.ndarray | list | tuple', distances: 'np.ndarray | list | tuple', trim: int, width: int) -> 'np.ndarray':
    jets=np.asarray(deltas);distances=np.asarray(distances)
    if jets.ndim!=5 or jets.shape[2]!=2 or jets.shape[-1]!=jets.shape[-2] or min(jets.shape)<1 or not np.isfinite(jets).all():
        raise ValueError('finite (B,S,2,P,P) density jets required')
    if not isinstance(width,(int,np.integer)) or width<1 or jets.shape[-1]%width or not isinstance(trim,(int,np.integer)) or trim<0:
        raise ValueError('integer width dividing P and nonnegative trim required')
    L=jets.shape[-1]//width
    if distances.ndim!=1 or len(distances)<1 or not np.isfinite(distances).all() or np.any(distances!=np.floor(distances)) or np.any(distances<0) or np.any(distances>=L-2*trim):
        raise ValueError('valid separations required')
    distances=distances.astype(int)
    B,S,_,P,_=jets.shape;L=P//width
    z=jets[:,:,0].reshape(B,S,L,width,L,width)
    dz=jets[:,:,1].reshape(B,S,L,width,L,width)
    result=np.zeros((B,3,len(distances)))
    for k,x in enumerate(distances):
        M=np.zeros((B,width,width));plus=np.zeros_like(M);minus=np.zeros_like(M)
        for i in range(trim,L-trim-x):
            a=z[:,:,i,:,i+x,:];da=dz[:,:,i,:,i+x,:];mag=abs(a);nonzero=mag>1e-12
            tangent=np.divide((a.conj()*da).real,mag,out=np.zeros_like(mag),where=nonzero)
            M+=np.where(nonzero,mag,0).mean(axis=1)/(L-2*trim-x)
            plus+=np.where(nonzero,tangent,abs(da)).mean(axis=1)/(L-2*trim-x)
            minus+=np.where(nonzero,-tangent,abs(da)).mean(axis=1)/(L-2*trim-x)
        for b in range(B):
            K=M[b].T@M[b];E,Q=np.linalg.eigh(K);result[b,0,k]=E[-1]
            U=Q[:,E>=E[-1]-1e-10*max(E[-1],1e-300)]
            for direction,Dm in enumerate((plus[b],minus[b]),1):
                G=Dm.T@M[b]+M[b].T@Dm
                result[b,direction,k]=np.linalg.eigvalsh(U.T@G@U)[-1]
    return result

